insert into public.resenas (id, producto_id, autor_nombre, pais, compra_verificada, variante, estrellas, titulo, texto, idioma, util_si, util_no, creado) values ('08ccf0ef-3623-4a85-abb5-79f06799bc2a', 'd4b3d54e-d45e-4247-a2df-b682b99f1700', 'Diego F.', 'PY', false, 'Lila, 256 GB', 4, 'Buen producto', 'Anda bien y vino completo. La caja llegó un poco golpeada, el producto no. Las fotos de noche salen mejor de lo que esperaba.', 'es', 33, 5, '2026-11-25T12:00:00.000Z'),
  ('4c5f654c-1572-417d-a474-887e02190bd9', 'd4b3d54e-d45e-4247-a2df-b682b99f1700', 'Fernanda L.', 'BR', true, 'Verde agua, 256 GB', 5, 'Tal cual la foto', 'Mi mamá está chocha con esto. Llegó antes de lo que decía.', 'es', 14, 2, '2026-11-25T12:00:00.000Z'),
  ('17d21825-4a39-448a-afe6-f3c07afb46c5', 'd4b3d54e-d45e-4247-a2df-b682b99f1700', 'Rafael S.', 'BR', true, 'Lilás, 256 GB', 4, 'Bom produto', 'Bom produto. Tiro uma estrela porque atrasou um dia, mas avisaram. Veio desbloqueado, coloquei o chip e funcionou.', 'pt', 17, 2, '2026-11-25T12:00:00.000Z'),
